//! CylindricalSurface3D collision tests//!//! 円柱サーフェスの衝突判定テスト#[cfg(test)]mod tests {    use crate::{CylindricalSurface3D, LineSegment3D, Plane3D, Point3D, Triangle3D, Vector3D};    use geo_foundation::extensions::BasicCollision;    const TOLERANCE: f64 = 1e-10;    fn create_test_cylinder() -> CylindricalSurface3D<f64> {        // Z軸方向、半径1.0の円柱        CylindricalSurface3D::new_z_axis(Point3D::origin(), 1.0).unwrap()    }    #[test]    fn test_point_on_surface() {        let cylinder = create_test_cylinder();        // 半径1.0、X軸上の点        let point_on_surface = Point3D::new(1.0, 0.0, 0.0);        assert!(cylinder.intersects(&point_on_surface, TOLERANCE));    }    #[test]    fn test_point_inside() {        let cylinder = create_test_cylinder();        // 半径0.5（円柱内部）        let point_inside = Point3D::new(0.5, 0.0, 0.0);        assert!(!cylinder.intersects(&point_inside, TOLERANCE));    }    #[test]    fn test_point_outside() {        let cylinder = create_test_cylinder();        // 半径2.0（円柱外部）        let point_outside = Point3D::new(2.0, 0.0, 0.0);        assert!(!cylinder.intersects(&point_outside, TOLERANCE));    }    #[test]    fn test_distance_to_point() {        let cylinder = create_test_cylinder();        // 半径1.0の面上の点        let point_on_surface = Point3D::new(1.0, 0.0, 0.0);        let dist = cylinder.distance_to(&point_on_surface);        assert!(dist.abs() < TOLERANCE);    }    #[test]    fn test_line_segment_intersection() {        let cylinder = create_test_cylinder();        // 円柱を貫通する線分        let start = Point3D::new(1.0, 0.0, -1.0);        let end = Point3D::new(1.0, 0.0, 1.0);        let segment = LineSegment3D::new(start, end);        assert!(cylinder.intersects(&segment, TOLERANCE));    }    #[test]    fn test_triangle_intersection() {        let cylinder = create_test_cylinder();        // 円柱面上に頂点を持つ三角形        let v1 = Point3D::new(1.0, 0.0, 0.0);        let v2 = Point3D::new(0.0, 1.0, 0.0);        let v3 = Point3D::new(0.0, 0.0, 1.0);        let triangle = Triangle3D::new(v1, v2, v3).unwrap();        assert!(cylinder.intersects(&triangle, TOLERANCE));    }    #[test]    fn test_plane_intersection() {        let cylinder = create_test_cylinder();        // XY平面（Z=0）        let origin = Point3D::origin();        let z_axis = Vector3D::new(0.0, 0.0, 1.0);        let x_axis = Vector3D::new(1.0, 0.0, 0.0);        let plane = Plane3D::from_origin_and_axes(origin, z_axis, x_axis).unwrap();        assert!(cylinder.intersects(&plane, TOLERANCE));    }    #[test]    fn test_self_intersection() {        let cylinder1 = create_test_cylinder();        let cylinder2 = CylindricalSurface3D::new_z_axis(Point3D::new(1.5, 0.0, 0.0), 1.0).unwrap();        // 半径1.0同士、中心間距離1.5 → 交差する        assert!(cylinder1.intersects(&cylinder2, TOLERANCE));    }    #[test]    fn test_no_self_intersection() {        let cylinder1 = create_test_cylinder();        let cylinder2 = CylindricalSurface3D::new_z_axis(Point3D::new(3.0, 0.0, 0.0), 1.0).unwrap();        // 半径1.0同士、中心間距離3.0 → 交差しない        assert!(!cylinder1.intersects(&cylinder2, TOLERANCE));    }}